#include <vector>
#include <iostream>

int main() {
    std::vector<int> vec(5);  // Creates a vector with 5 elements, stored contiguously in memory
    vec[10] = 42;  // Accesses an out-of-bounds index; no runtime check is performed
    std::cout << vec[10] << std::endl;  // Further undefined behavior
    return 0;
}
